/**
 * Base des indicateurs de gestion financière (SYSCOHADA révisé). Chaque fiche : formule lisible,
 * unité, sens favorable, repères usuels (ajustés au secteur), lectures et réflexes.
 *
 * Les repères sont des CONVENTIONS usuelles de l'analyse financière, jamais des normes : ils sont
 * affichés comme tels et doivent être validés par l'encadreur [À VÉRIFIER par un enseignant de finance].
 */
import type { Bands, IndicatorDef, Norms } from "./types";

const USUEL = "Repère usuel de l'analyse financière, à adapter au secteur et à valider avec votre encadreur.";
const norms = (good: number, bad: number, bySector?: Norms["bySector"]): Norms => ({ default: { good, bad }, bySector, note: USUEL });
const sign: Bands = { good: 0, bad: 0 };
const signNorms: Norms = { default: sign, note: "Un montant positif est favorable, un montant négatif défavorable." };

type Def = Omit<IndicatorDef, "requires" | "aliases"> & { requires?: IndicatorDef["requires"]; aliases?: string[] };
const def = (d: Def): IndicatorDef => ({ requires: ["bilan"], aliases: [], ...d });
const cr = (d: Def): IndicatorDef => def({ requires: ["cr"], ...d });
const mixed = (d: Def): IndicatorDef => def({ requires: ["bilan", "cr"], ...d });
const tft = (d: Def): IndicatorDef => def({ requires: ["tft"], ...d });

